```c
/**
 * Look up where the data for a given block of a copy-on-write export
 * is stored in the session's diff file.
 *
 * @param client client with an active copy-on-write diff file
 * @param block block number (offset / DIFFPAGESIZE)
 * @return the offset of the block's data in the diff file, 0 if the
 * block has not been written during this session, or -1 on error
 */
static off_t diff_block_offset(CLIENT *client, uint64_t block) {
	off_t pos = 0;
	ssize_t ret;

	do {
		ret = pread(client->difffd, &pos, sizeof(pos), (off_t)(block * sizeof(pos)));
	} while(ret == -1 && errno == EINTR);
	if(ret != sizeof(pos))
		return -1;
	return pos;
}

static int diff_set_block_offset(CLIENT *client, uint64_t block, off_t pos) {
	ssize_t ret;
	do {
		ret = pwrite(client->difffd, &pos, sizeof(pos), (off_t)(block * sizeof(pos)));
	} while(ret == -1 && errno == EINTR);
	return ret == sizeof(pos) ? 0 : -1;
}
```

