Place right after get_filepos (before rawexpwrite). Also need to modify rawexpwrite/rawexpread.

Let me write the full code block:

```c
/**
 * Read an amount of bytes at a given offset from the exported file(s),
 * bypassing the copy-on-write diff file.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error.
 **/
static ssize_t masterexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	int fhandle;
	off_t foffset;
	size_t maxbytes;
	ssize_t retval;

	if(get_filepos(client, a, &fhandle, &foffset, &maxbytes))
		return -1;
	if(maxbytes && len > maxbytes)
		len = maxbytes;

	retval = pread(fhandle, buf, len, foffset);
	if (client->server->flags & F_TREEFILES) {
		close(fhandle);
	}
	return retval;
}
```

Hmm, wait — should rawexpread just call masterexpread instead of duplicating its body? Yes! Restructure:

```c
ssize_t rawexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	DEBUG("(READ from ... ), ");  -- hmm, the DEBUG inside rawexpread uses fhandle...
```

The existing DEBUG in rawexpread prints fhandle and foffset. Moving the body to masterexpread preserves that. rawexpread becomes:

```c
ssize_t rawexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	if(client->difffd != -1)
		return cowexpread(a, buf, len, client);
	return masterexpread(a, buf, len, client);
}
```

Clean and minimal duplication.

Next the diff file index helpers:

```c
/**
 * Number of DIFFPAGESIZE-sized blocks in the export, i.e. the number
 * of entries in the copy-on-write diff file's index.
 */
static uint64_t diff_nblocks(CLIENT *client) {
	return (client->exportsize + DIFFPAGESIZE - 1) / DIFFPAGESIZE;
}

/**
 * Size of the index at the start of a copy-on-write diff file, which
 * holds one position per block of the export.
 */
static off_t diff_index_size(CLIENT *client) {
	return (off_t)(diff_nblocks(client) * sizeof(off_t));
}

/**
 * Look up the position of a block's data in the copy-on-write diff
 * file of this session.
 *
 * @param client client whose diff file we're reading
 * @param block block number (export offset divided by DIFFPAGESIZE)
 * @return the offset of the block's data within the diff file, 0 if
 * the block was not written during this session, or -1 in case of an
 * error
 **/
static off_t diff_lookup(CLIENT *client, uint64_t block) {
	off_t pos = 0;
	ssize_t ret;

	do {
		ret = pread(client->difffd, &pos, sizeof(pos),
				(off_t)(block * sizeof(pos)));
	} while(ret == -1 && errno == EINTR);
	if(ret != sizeof(pos))
		return -1;
	return pos;
}

/**
 * Record the position of a block's data in the copy-on-write diff
 * file of this session.
 *
 * @return 0 on success, -1 in case of an error
 **/
static int diff_store(CLIENT *client, uint64_t block, off_t pos) {
	ssize_t ret;

	do {
		ret = pwrite(client->difffd, &pos, sizeof(pos),
				(off_t)(block * sizeof(pos)));
	} while(ret == -1 && errno == EINTR);
	return (ret == sizeof(pos)) ? 0 : -1;
}
```

Wait — block * sizeof(pos): uint64_t * size_t → uint64_t, cast to off_t. For very large exports this could overflow off_t… exportsize itself fits in off_t; the index is 8 bytes per 4096 bytes of export → index_size = exportsize/512 which fits if exportsize fits… off_t max is ~9.2e18; exportsize/512 < exportsize — fine.

Write to a single block:

```c
/**
 * Write a block's data into the copy-on-write diff file of this
 * session, allocating space for it if this is the first time the
 * block is written.
 *
 * @param client client whose diff file we're writing
 * @param block block number (export offset divided by DIFFPAGESIZE)
 * @param buf the block's new contents
 * @param len number of valid bytes in buf, at most DIFFPAGESIZE
 * @return 0 on success, -1 in case of an error
 **/
static int diff_write_block(CLIENT *client, uint64_t block, const char *buf, size_t len) {
	off_t pos;
	ssize_t ret;

	pos = diff_lookup(client, block);
	if(pos < 0)
		return -1;
	if(pos == 0) {
		if(client->server->flags & F_SPARSE) {
			pos = diff_index_size(client) +
					(off_t)(block * DIFFPAGESIZE);
		} else {
			do {
				pos = lseek(client->difffd, 0, SEEK_END);
			} while(pos == -1 && errno == EINTR);
			if(pos < 0)
				return -1;
		}
		if(diff_store(client, block, pos))
			return -1;
	}
	do {
		ret = pwrite(client->difffd, buf, len, pos);
	} while(ret == -1 && errno == EINTR);
	return (ret == (ssize_t)len) ? 0 : -1;
}
```

Hmm — if pwrite returns short (ret < len, ret >= 0): the `do..while` exits (ret != -1), return -1. errno could be stale (0)… set errno = EIO on short write? Let me handle it: if ret>=0 && ret<len → errno = ENOSPC? Actually, short pwrite to a regular file usually means ENOSPC happened. If errno == 0, set errno = EIO. Simple:

```c
	if(ret == -1 || ret != (ssize_t)len) {   // hmm
```

Let me write it this way:
```c
	do {
		ret = pwrite(client->difffd, buf, len, pos);
	} while(ret == -1 && errno == EINTR);
	if(ret != (ssize_t)len) {
		if(ret >= 0)
			errno = EIO;
		return -1;
	}
	return 0;
```

Same pattern for master reads etc. — keep consistent.

Then cowexpread and cowexpwrite:

```c
/**
 * Read from a copy-on-write export. Blocks that were written during
 * this session are read from the diff file; all other blocks are read
 * from the exported file.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t cowexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	uint64_t block = a / DIFFPAGESIZE;
	size_t block_off = a % DIFFPAGESIZE;
	size_t done = 0;

	DEBUG("(COW READ offset %llu len %u), ", (unsigned long long)a, (unsigned int)len);

	pthread_mutex_lock(&client->diff_lock);
	while(done < len) {
		size_t chunk = DIFFPAGESIZE - block_off;
		off_t pos;
		ssize_t ret;

		if(chunk > len - done)
			chunk = len - done;
		pos = diff_lookup(client, block);
		if(pos < 0) {
			pthread_mutex_unlock(&client->diff_lock);
			return -1;
		}
		if(pos > 0) {
			do {
				ret = pread(client->difffd, buf + done, chunk,
						pos + block_off);
			} while(ret == -1 && errno == EINTR);
		} else {
			ret = masterexpread(a + done, buf + done, chunk, client);
		}
		if(ret <= 0) {
			pthread_mutex_unlock(&client->diff_lock);
			return ret;
		}
		done += ret;
		block_off += ret;
		if(block_off >= DIFFPAGESIZE) {
			block++;
			block_off = 0;
		}
	}
	pthread_mutex_unlock(&client->diff_lock);
	return done;
}
```

Note: block_off += ret, where ret ≤ chunk ≤ DIFFPAGESIZE - block_off → block_off ≤ DIFFPAGESIZE. Use `==` rather than `>=`… `>=` is safe.

```c
/**
 * Write to a copy-on-write export. Data is written to the session's
 * diff file rather than to the exported file. Blocks that are only
 * partially written are completed with their current contents first.
 *
 * @param a The offset where the write should start
 * @param buf The buffer to write from
 * @param len The length of buf
 * @param client The client we're serving for
 * @param fua Flag to indicate 'Force Unit Access'
 * @return The number of bytes actually written, or -1 in case of an error
 **/
static ssize_t cowexpwrite(off_t a, char *buf, size_t len, CLIENT *client, int fua) {
	uint64_t block = a / DIFFPAGESIZE;
	size_t block_off = a % DIFFPAGESIZE;
	size_t done = 0;
	char blockbuf[DIFFPAGESIZE];

	DEBUG("(COW WRITE offset %llu len %u fua %d), ", (unsigned long long)a, (unsigned int)len, fua);

	pthread_mutex_lock(&client->diff_lock);
	while(done < len) {
		size_t chunk = DIFFPAGESIZE - block_off;
		int ret;

		if(chunk > len - done)
			chunk = len - done;
		if(chunk == DIFFPAGESIZE) {
			ret = diff_write_block(client, block, buf + done, chunk);
		} else {
			/*
			 * Partial block: read the block's current
			 * contents, update them, and write the whole
			 * block to the diff file.
			 */
			off_t bstart = (off_t)(block * DIFFPAGESIZE);
			size_t blen = DIFFPAGESIZE;
			off_t pos;
			ssize_t r;

			if(client->exportsize - bstart < DIFFPAGESIZE)
				blen = client->exportsize - bstart;
			pos = diff_lookup(client, block);
			if(pos < 0)
				goto out_err;
			memset(blockbuf, 0, blen);
			if(pos > 0) {
				do {
					r = pread(client->difffd, blockbuf, blen, pos);
				} while(r == -1 && errno == EINTR);
			} else {
				r = masterexpread(bstart, blockbuf, blen, client);
			}
			if(r < 0)
