/**
 * Size of the index at the start of a copy-on-write diff file. The
 * index holds one position per DIFFPAGESIZE-sized block of the
 * export; a zero entry means the block was not written during this
 * session.
 **/
static off_t diff_index_size(CLIENT *client) {
	return (off_t)(((client->exportsize + DIFFPAGESIZE - 1) / DIFFPAGESIZE) * sizeof(off_t));
}

/**
 * Look up the position of a block's data in the copy-on-write diff
 * file of this session.
 *
 * @param client client whose diff file we're reading
 * @param block block number (export offset divided by DIFFPAGESIZE)
 * @return the offset of the block's data within the diff file, 0 if
 * the block was not written during this session, or -1 in case of an
 * error
 **/
static off_t diff_lookup(CLIENT *client, uint64_t block) {
	off_t pos = 0;
	ssize_t ret;

	do {
		ret = pread(client->difffd, &pos, sizeof(pos),
				(off_t)(block * sizeof(pos)));
	} while(ret == -1 && errno == EINTR);
	if(ret != sizeof(pos)) {
		if(ret >= 0)
			errno = EIO;
		return -1;
	}
	return pos;
}

/**
 * Record the position of a block's data in the copy-on-write diff
 * file of this session.
 *
 * @return 0 on success, -1 in case of an error
 **/
static int diff_store(CLIENT *client, uint64_t block, off_t pos) {
	ssize_t ret;

	do {
		ret = pwrite(client->difffd, &pos, sizeof(pos),
				(off_t)(block * sizeof(pos)));
	} while(ret == -1 && errno == EINTR);
	if(ret != sizeof(pos)) {
		if(ret >= 0)
			errno = EIO;
		return -1;
	}
	return 0;
}

/**
 * Write a block's data into the copy-on-write diff file of this
 * session, allocating space for it if the block has not been written
 * before. Without sparse_cow, new blocks are appended at the end of
 * the diff file; with sparse_cow, they are stored at the offset they
 * have in the export, keeping the diff file sparse.
 *
 * @param client client whose diff file we're writing
 * @param block block number (export offset divided by DIFFPAGESIZE)
 * @param buf the block's new contents
 * @param len number of valid bytes in buf, at most DIFFPAGESIZE
 * @return 0 on success, -1 in case of an error
 **/
static int diff_write_block(CLIENT *client, uint64_t block, const char *buf, size_t len) {
	off_t pos;
	ssize_t ret;

	pos = diff_lookup(client, block);
	if(pos < 0)
		return -1;
	if(pos == 0) {
		if(client->server->flags & F_SPARSE) {
			pos = diff_index_size(client) +
					(off_t)(block * DIFFPAGESIZE);
		} else {
			do {
				pos = lseek(client->difffd, 0, SEEK_END);
			} while(pos == -1 && errno == EINTR);
			if(pos < 0)
				return -1;
		}
		if(diff_store(client, block, pos))
			return -1;
	}
	do {
		ret = pwrite(client->difffd, buf, len, pos);
	} while(ret == -1 && errno == EINTR);
	if(ret != (ssize_t)len) {
		if(ret >= 0)
			errno = EIO;
		return -1;
	}
	return 0;
}

/**
 * Read an amount of bytes at a given offset from the exported file(s),
 * retrying over file boundaries of the multiple file option.
 *
 * @return 0 on success, -1 in case of an error
 **/
static int masterexpread_fully(off_t a, char *buf, size_t len, CLIENT *client) {
	size_t done = 0;

	while(done < len) {
		ssize_t ret = masterexpread(a + done, buf + done, len - done, client);
		if(ret <= 0) {
			if(ret == 0)
				errno = EIO;
			return -1;
		}
		done += ret;
	}
	return 0;
}

/**
 * Read from a copy-on-write export. Blocks that were written during
 * this session are read from the diff file, all other blocks from the
 * exported file.
 *
 * @param a The offset where the read should start
 * @param buf A buffer to read into
 * @param len The size of buf
 * @param client The client we're serving for
 * @return The number of bytes actually read, or -1 in case of an error
 **/
static ssize_t cowexpread(off_t a, char *buf, size_t len, CLIENT *client) {
	uint64_t block = a / DIFFPAGESIZE;
	size_t block_off = a % DIFFPAGESIZE;
	size_t done = 0;

	DEBUG("(COW READ offset %llu len %u), ", (unsigned long long)a, (unsigned int)len);

	pthread_mutex_lock(&client->diff_lock);
	while(done < len) {
		size_t chunk = DIFFPAGESIZE - block_off;
		off_t pos;
		ssize_t ret;

		if(chunk > len - done)
			chunk = len - done;
		pos = diff_lookup(client, block);
		if(pos < 0)
			goto out_err;
		if(pos > 0) {
			do {
				ret = pread(client->difffd, buf + done, chunk,
						pos + block_off);
			} while(ret == -1 && errno == EINTR);
			if(ret == -1)
				goto out_err;
			if(ret == 0)
				errno = EIO;
			if(ret <= 0)
				goto out_err;
		} else {
			ret = masterexpread(a + done, buf + done, chunk, client);
			if(ret <= 0)
				goto out_err;
		}
		done += ret;
		block_off += ret;
		if(block_off == DIFFPAGESIZE) {
			block++;
			block_off = 0;
		}
	}
	pthread_mutex_unlock(&client->diff_lock);
	return done;
out_err:
	pthread_mutex_unlock(&client->diff_lock);
	return -1;
}

