/*
 * Throwaway test client for edge cases of nbd-server copy-on-write
 * exports: exports whose size is not a multiple of the diff block
 * size, WRITE_ZEROES, TRIM and FLUSH.
 *
 * usage: extra-client <port> <masterfile>
 * Exits 0 on success, 1 on failure.
 */

#include <sys/types.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>

#include "config.h"
#include "lfs.h"

#define MY_NAME "extra-client"
#include "cliserv.h"

#define DEVICESIZE 10000ULL	/* not a multiple of 4096 */

static void fail(const char *msg) {
	fprintf(stderr, "extra-client: %s\n", msg);
	exit(1);
}

static int connect_tcp(const char *port) {
	struct sockaddr_in addr;
	int sock;

	sock = socket(AF_INET, SOCK_STREAM, 0);
	if(sock < 0) {
		fail("could not create socket");
	}
	memset(&addr, 0, sizeof(addr));
	addr.sin_family = AF_INET;
	addr.sin_port = htons(atoi(port));
	addr.sin_addr.s_addr = htonl(0x7f000001);
	if(connect(sock, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
		fail("could not connect");
	}
	return sock;
}

static void negotiate_go(int sock, const char *exportname) {
	char init_passwd[8];
	uint64_t magic;
	uint16_t sflags;
	uint32_t cflags;
	uint32_t namelen;
	uint32_t optlen;
	uint32_t type;
	uint32_t len;
	uint16_t n_requests;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t len;
	} __attribute__((packed)) optreq;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t type;
		uint32_t len;
	} __attribute__((packed)) optrep;
	char scratch[4096];

	if(readit(sock, init_passwd, 8) < 0) {
		fail("could not read initial magic");
	}
	if(memcmp(init_passwd, INIT_PASSWD, 8) != 0) {
		fail("initial magic mismatch");
	}
	if(readit(sock, &magic, 8) < 0) {
		fail("could not read options magic");
	}
	if(ntohll(magic) != 0x49484156454F5054LL) {
		fail("options magic mismatch");
	}
	if(readit(sock, &sflags, 2) < 0) {
		fail("could not read handshake flags");
	}
	cflags = htonl(NBD_FLAG_C_FIXED_NEWSTYLE | NBD_FLAG_C_NO_ZEROES);
	if(writeit(sock, &cflags, 4) < 0) {
		fail("could not send client flags");
	}

	namelen = strlen(exportname);
	n_requests = 0;
	optlen = namelen + sizeof(namelen) + sizeof(n_requests);
	optreq.magic = htonll(0x49484156454F5054LL);
	optreq.opt = htonl(NBD_OPT_GO);
	optreq.len = htonl(optlen);
	namelen = htonl(namelen);
	n_requests = htons(n_requests);
	if(writeit(sock, &optreq, sizeof(optreq)) < 0) {
		fail("could not send option request");
	}
	if(writeit(sock, &namelen, sizeof(namelen)) < 0) {
		fail("could not send export name length");
	}
	if(writeit(sock, exportname, ntohl(namelen)) < 0) {
		fail("could not send export name");
	}
	if(writeit(sock, &n_requests, sizeof(n_requests)) < 0) {
		fail("could not send info request count");
	}

	while(1) {
		if(readit(sock, &optrep, sizeof(optrep)) < 0) {
			fail("could not read option reply");
		}
		if(ntohll(optrep.magic) != NBD_OPT_REPLY_MAGIC) {
			fail("option reply magic mismatch");
		}
		type = ntohl(optrep.type);
		len = ntohl(optrep.len);
		if(len > sizeof(scratch)) {
			fail("option reply too long");
		}
		if(readit(sock, scratch, len) < 0) {
			fail("could not read option reply data");
		}
		if(type & NBD_REP_FLAG_ERROR) {
			fail("server sent error reply to NBD_OPT_GO");
		}
		if(type == NBD_REP_ACK) {
			return;
		}
	}
}

static int do_io(int sock, uint32_t cmd, uint64_t from, unsigned char *buf,
		 uint32_t len, uint32_t *rerror) {
	struct nbd_request req;
	struct nbd_reply rep;
	static uint64_t cookie = 0;

	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(cmd);
	req.cookie = htonll(++cookie);
	req.from = htonll(from);
	req.len = htonl(len);
	if(writeit(sock, &req, sizeof(req)) < 0) {
		return -1;
	}
	if(cmd == NBD_CMD_WRITE) {
		if(writeit(sock, buf, len) < 0) {
			return -1;
		}
	}
	if(readit(sock, &rep, sizeof(rep)) < 0) {
		return -1;
	}
	if(rep.magic != htonl(NBD_REPLY_MAGIC)) {
		fail("reply magic mismatch");
	}
	if(rep.cookie != req.cookie) {
		fail("cookie mismatch");
	}
	*rerror = ntohl(rep.error);
	if(*rerror != 0) {
		return 0;
	}
	if(cmd == NBD_CMD_READ) {
		if(readit(sock, buf, len) < 0) {
			return -1;
		}
	}
	return 0;
}

static void check_region(int sock, uint64_t off, uint32_t len,
			 unsigned char expect) {
	unsigned char buf[DEVICESIZE];
	uint32_t error;
	uint32_t i;

	if(do_io(sock, NBD_CMD_READ, off, buf, len, &error) < 0) {
		fail("read failed");
	}
	if(error != 0) {
		fprintf(stderr, "extra-client: read error %u at %llu\n",
			error, (unsigned long long)off);
		exit(1);
	}
	for(i = 0; i < len; i++) {
		if(buf[i] != expect) {
			fprintf(stderr, "extra-client: mismatch at %llu:"
				" got %02x want %02x\n",
				(unsigned long long)(off + i), buf[i],
				expect);
			exit(1);
		}
	}
}

int main(int argc, char *argv[]) {
	unsigned char buf[DEVICESIZE];
	unsigned char master[DEVICESIZE];
	uint32_t error;
	int sock;
	int fd;
	uint64_t i;

	if(argc != 3) {
		fprintf(stderr, "usage: extra-client <port> <masterfile>\n");
		return 1;
	}

	fd = open(argv[2], O_RDONLY);
	if(fd < 0) {
		fail("could not open master file");
	}
	if(read(fd, master, DEVICESIZE) != DEVICESIZE) {
		fail("short read on master file");
	}
	close(fd);

	sock = connect_tcp(argv[1]);
	negotiate_go(sock, "extra");

	/* pattern write covering the whole export, including the
	 * partial final block */
	memset(buf, 0xA1, DEVICESIZE);
	if(do_io(sock, NBD_CMD_WRITE, 0, buf, DEVICESIZE, &error) < 0) {
		fail("write failed");
	}
	if(error != 0) {
		fprintf(stderr, "extra-client: write error %u\n", error);
		return 1;
	}
	check_region(sock, 0, DEVICESIZE, 0xA1);

	/* write_zeroes over an unaligned multi-block range */
	if(do_io(sock, NBD_CMD_WRITE_ZEROES, 4000, NULL, 3000, &error) < 0) {
		fail("write_zeroes failed");
	}
	if(error != 0) {
		fprintf(stderr, "extra-client: write_zeroes error %u\n",
			error);
		return 1;
	}
	check_region(sock, 0, 4000, 0xA1);
	check_region(sock, 4000, 3000, 0x00);
	check_region(sock, 7000, DEVICESIZE - 7000, 0xA1);

	/* rewrite only the tail of the final partial block */
	memset(buf, 0xB2, 500);
	if(do_io(sock, NBD_CMD_WRITE, 9500, buf, 500, &error) < 0) {
		fail("tail write failed");
	}
	if(error != 0) {
		fprintf(stderr, "extra-client: tail write error %u\n",
			error);
		return 1;
	}
	check_region(sock, 9000, 500, 0xA1);
	check_region(sock, 9500, 500, 0xB2);

	/* trim and flush must at least not fail */
	if(do_io(sock, NBD_CMD_TRIM, 0, NULL, 4096, &error) < 0) {
		fail("trim failed");
	}
	if(error != 0) {
		fprintf(stderr, "extra-client: trim error %u\n", error);
		return 1;
	}
	if(do_io(sock, NBD_CMD_FLUSH, 0, NULL, 0, &error) < 0) {
		fail("flush failed");
	}
	if(error != 0) {
		fprintf(stderr, "extra-client: flush error %u\n", error);
		return 1;
	}

	/* out of bounds write must be rejected, not crash the server */
	if(do_io(sock, NBD_CMD_WRITE, 9999, buf, 2, &error) < 0) {
		fail("oob write failed to get a reply");
	}
	if(error == 0) {
		fail("out of bounds write was accepted");
	}

	/* disconnect */
	struct nbd_request req;
	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(NBD_CMD_DISC);
	req.cookie = 0;
	req.from = 0;
	req.len = 0;
	if(writeit(sock, &req, sizeof(req)) < 0) {
		fail("disconnect failed");
	}
	close(sock);

	/* master file must be untouched */
	fd = open(argv[2], O_RDONLY);
	if(fd < 0) {
		fail("could not reopen master file");
	}
	if(read(fd, buf, DEVICESIZE) != DEVICESIZE) {
		fail("short read on master file after disconnect");
	}
	close(fd);
	for(i = 0; i < DEVICESIZE; i++) {
		if(buf[i] != master[i]) {
			fprintf(stderr, "extra-client: master changed at"
				" %llu\n", (unsigned long long)i);
			return 1;
		}
	}
	printf("extra-client: all checks passed\n");
	return 0;
}

